package com.bananalab.lite;
import android.content.*;
import org.json.*;import java.net.URL;import java.util.*;
/** A sub-link reading that continues outside the chat: the first page is read at once, the rest in slices run by the
 *  learning service. Its queue is saved, so it survives closing the app and can be paused, resumed or cancelled. */
final class CrawlJob{
 static final int STEP_PAGES=25,SAVED_QUEUE=5000,PER_HOST=15,EXPLORE_PAGES=60,EXPLORE_DEPTH=2,MIN_TEXT=500,HASHES=3000;static final long STEP_MS=50000L;
 /** Sites that are mostly sign-in walls, video or shops: an open exploration does not spend its page budget there. */
 static final java.util.regex.Pattern AVOID=java.util.regex.Pattern.compile("(?:^|\\.)(?:facebook|instagram|twitter|x|tiktok|youtube|youtu|linkedin|pinterest|whatsapp|telegram|t|reddit|amazon|mercadolibre|ebay|aliexpress|apple|google|bing|duckduckgo|microsoft|spotify|netflix|twitch|discord|snapchat|paypal)\\.(?:com|be|me|co|tv|net|org)(?:\\.[a-z]{2})?$");
 static final Map<String,PageCrawl.Robots> ROBOTS=new HashMap<>();
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-crawl-job",0);}
 static JSONObject state(Context c)throws Exception{String raw=prefs(c).getString("job","");return raw.isEmpty()?null:new JSONObject(raw);}
 static void save(Context c,JSONObject s)throws Exception{if(!prefs(c).edit().putString("job",s.toString()).commit())throw new java.io.IOException("No pude guardar el recorrido");}
 static boolean active(JSONObject s){return s!=null&&!s.optBoolean("done");}
 static boolean pending(Context c){try{JSONObject s=state(c);return active(s)&&!s.optBoolean("paused");}catch(Exception e){return false;}}
 static void store(JSONObject s,ArrayDeque<String[]> queue)throws Exception{JSONArray rows=new JSONArray();int n=0;for(String[] item:queue){if(n++>=SAVED_QUEUE)break;rows.put(new JSONArray().put(item[0]).put(Integer.parseInt(item[1])));}s.put("queue",rows).put("pending",queue.size());}
 /** Reads the page the user sent, saves it and queues its links. An error here is thrown and nothing is queued. */
 static String start(Context c,PageCrawl.Plan plan,KnowledgeNotebook.PageLoader pages,PageCrawl.Saver saver)throws Exception{return start(c,plan,pages,saver,false);}
 /** Links of a page towards any public site, for an open exploration. */
 static void collectOpen(PageReader.Document d,URL base,int level,int maxDepth,Set<String> seen,ArrayDeque<String[]> queue){if(level>maxDepth)return;for(String href:d.links){if(queue.size()>=PageCrawl.MAX_QUEUE||seen.size()>=PageCrawl.MAX_QUEUE*4)return;String url=PageCrawl.resolve(base,href);if(url==null)continue;try{String host=new URL(url).getHost().toLowerCase(Locale.ROOT);if(!ResearchWeb.safeHost(host)||AVOID.matcher(host).find())continue;}catch(Exception e){continue;}if(seen.add(PageCrawl.key(url)))queue.add(new String[]{url,Integer.toString(level)});}}
 static JSONObject blank(String url,int depth,int pages,String note)throws Exception{JSONArray levels=new JSONArray();for(int i=0;i<=PageCrawl.MAX_DEPTH;i++)levels.put(0);return new JSONObject().put("url",url).put("depth",depth).put("pages",pages).put("note",note).put("started",System.currentTimeMillis()).put("saved",0).put("failed",0).put("robots",0).put("outside",0).put("deepest",0).put("levels",levels).put("savedKeys",new JSONArray()).put("titles",new JSONArray()).put("errors",new JSONArray()).put("paused",false).put("done",false).put("end","").put("receipt","").put("open",false).put("hosts",new JSONObject()).put("hashes",new JSONArray()).put("short",0).put("repeated",0).put("offTopic",0).put("hostFull",0).put("topic",new JSONArray());}
 /** Starts an exploration from search results: nothing is read in the chat, every page is read in the background. */
 static String explore(Context c,String topic,List<String> seeds,int depth,int pages)throws Exception{JSONObject old=state(c);if(active(old))throw new IllegalStateException("Ya hay un recorrido en curso desde "+old.getString("url")+" ("+old.getInt("saved")+" páginas guardadas). Esperá a que termine, o decí «cancelá el recorrido» antes de empezar otro.");if(seeds.isEmpty())throw new java.io.IOException("El buscador no devolvió páginas para empezar");JSONObject s=blank("búsqueda: "+topic,depth,pages,"").put("open",true).put("site","internet").put("host","");JSONArray terms=new JSONArray();for(String w:ReadingKnowledge.words(topic))terms.put(w);s.put("topic",terms).put("topicText",topic);ArrayDeque<String[]> queue=new ArrayDeque<>();Set<String> seen=new HashSet<>();for(String url:seeds)if(seen.add(PageCrawl.key(url)))queue.add(new String[]{url,"0"});store(s,queue);save(c,s);
  return "Empiezo a explorar internet sobre «"+topic+"» desde "+queue.size()+(queue.size()==1?" página":" páginas")+" del buscador. Leo en segundo plano hasta "+pages+" páginas, "+depth+(depth==1?" nivel":" niveles")+" de enlaces y como mucho "+PER_HOST+" por sitio; salteo páginas repetidas, con poco texto o que no nombran el tema.\nDecí «estado del recorrido», «pausá el recorrido» o «cancelá el recorrido». No verifico lo que dicen esas páginas.";}
 static String start(Context c,PageCrawl.Plan plan,KnowledgeNotebook.PageLoader pages,PageCrawl.Saver saver,boolean open)throws Exception{JSONObject old=state(c);if(active(old))throw new IllegalStateException("Ya hay un recorrido en curso desde "+old.getString("url")+" ("+old.getInt("saved")+" páginas guardadas). Esperá a que termine, o decí «cancelá el recorrido» antes de empezar otro.");
  Set<String> seen=new HashSet<>();ArrayDeque<String[]> queue=new ArrayDeque<>();JSONObject s=blank(plan.url,plan.depth,plan.pages,plan.note).put("open",open);JSONArray keys=s.getJSONArray("savedKeys"),titles=s.getJSONArray("titles"),levels=s.getJSONArray("levels");levels.put(0,1);String receipt;
  try(PageReader.Document d=pages.load(plan.url)){URL first=new URL(d.url);String site=PageCrawl.site(first.getHost());seen.add(PageCrawl.key(plan.url));seen.add(PageCrawl.key(d.url));receipt=saver.save(d);keys.put(PageCrawl.key(plan.url));if(!PageCrawl.key(d.url).equals(PageCrawl.key(plan.url)))keys.put(PageCrawl.key(d.url));titles.put(d.title);s.put("site",site).put("host",first.getHost());s.getJSONObject("hosts").put(first.getHost().toLowerCase(Locale.ROOT),1);if(open)s.getJSONArray("hashes").put(fingerprint(d.text));if(open)collectOpen(d,first,1,plan.depth,seen,queue);else PageCrawl.collect(d,first,site,1,plan.depth,seen,queue);}
  s.put("saved",1).put("done",queue.isEmpty()).put("end",queue.isEmpty()?"La página no tenía subenlaces legibles del mismo sitio.":"").put("receipt",receipt);store(s,queue);save(c,s);
  if(queue.isEmpty())return plan.note+receipt+"\nLa página no tenía subenlaces legibles del mismo sitio, así que no hay nada más que recorrer.";
  return plan.note+"Guardé la página inicial y encontré "+queue.size()+(open?" enlaces, también hacia otros sitios (como mucho "+PER_HOST+" páginas por sitio)":" subenlaces de "+s.getString("site"))+". Los sigo leyendo en segundo plano: hasta "+plan.depth+(plan.depth==1?" nivel":" niveles")+" y "+plan.pages+" páginas. Podés seguir conversando.\nDecí «estado del recorrido» para ver cómo va, «pausá el recorrido» o «cancelá el recorrido». Si cerrás Banana, continúa cuando la vuelvas a abrir. Avanza mientras el aprendizaje continuo esté activo y haya batería suficiente.";}
 static String brief(Exception e){return PageCrawl.brief(e);}
 static PageCrawl.Robots rules(String host,KnowledgeNotebook.PageLoader pages){PageCrawl.Robots r;synchronized(ROBOTS){r=ROBOTS.get(host);}if(r==null){r=PageCrawl.robots("https://"+host,pages);synchronized(ROBOTS){if(ROBOTS.size()>400)ROBOTS.clear();ROBOTS.put(host,r);}}return r;}
 /** Letters and digits of the start of the text, so that the same article on two addresses is recognised. */
 static String fingerprint(String text){StringBuilder b=new StringBuilder();for(int i=0;i<text.length()&&b.length()<600;i++){char ch=Character.toLowerCase(text.charAt(i));if(Character.isLetterOrDigit(ch))b.append(ch);}try{return JavaMethodEditor.hash(b.toString()).substring(0,16);}catch(Exception e){return Integer.toHexString(b.toString().hashCode());}}
 /** Why a page is not worth keeping in an open exploration ("short", "repeated", "offTopic"), or null to keep it. */
 static String quality(String text,JSONArray topic,Set<String> known)throws Exception{if(text.trim().length()<MIN_TEXT)return "short";if(known.contains(fingerprint(text)))return "repeated";if(topic.length()>0){Set<String> words=ReadingKnowledge.words(text);int hit=0;for(int i=0;i<topic.length()&&hit==0;i++){String term=topic.getString(i),stem=term.substring(0,Math.min(term.length(),5));for(String w:words)if(w.startsWith(stem)||term.length()>=4&&stem.startsWith(w)&&w.length()>=4){hit++;break;}}if(hit==0)return "offTopic";}return null;}
 /** Reads up to maxPages more pages or until the time slice ends. Returns whether pages remain to be read. */
 static boolean step(Context c,KnowledgeNotebook.PageLoader pages,PageCrawl.Saver saver,int maxPages,long budgetMs)throws Exception{JSONObject s=state(c);if(!active(s)||s.optBoolean("paused"))return false;long deadline=System.nanoTime()+budgetMs*1000000L;String site=s.getString("site");int depth=s.getInt("depth"),cap=s.getInt("pages");
  Set<String> seen=new HashSet<>();JSONArray keys=s.getJSONArray("savedKeys");for(int i=0;i<keys.length();i++)seen.add(keys.getString(i));ArrayDeque<String[]> queue=new ArrayDeque<>();JSONArray rows=s.getJSONArray("queue");for(int i=0;i<rows.length();i++){JSONArray r=rows.getJSONArray(i);queue.add(new String[]{r.getString(0),Integer.toString(r.getInt(1))});seen.add(PageCrawl.key(r.getString(0)));}
  final boolean open=s.optBoolean("open");JSONObject hosts=s.getJSONObject("hosts");JSONArray hashes=s.getJSONArray("hashes"),topic=s.getJSONArray("topic");Set<String> known=new HashSet<>();for(int i=0;i<hashes.length();i++)known.add(hashes.getString(i));PageCrawl.Robots robots=open?null:rules(s.getString("host"),pages);long wait=open?PageCrawl.pauseMs:Math.max(PageCrawl.pauseMs,Math.min(robots.delayMs,5000));JSONArray levels=s.getJSONArray("levels"),titles=s.getJSONArray("titles"),errors=s.getJSONArray("errors");int read=0;String end="";
  while(!queue.isEmpty()){if(s.getInt("saved")>=cap){end="Llegué al tope de "+cap+" páginas.";break;}if(read>=maxPages||System.nanoTime()>deadline)break;if(Thread.currentThread().isInterrupted()||LearningLoop.busy)break;JSONObject fresh=state(c);if(fresh==null||fresh.optBoolean("paused")||fresh.optLong("started")!=s.getLong("started"))return false;
   String[] next=queue.poll();String url=next[0];int level=Integer.parseInt(next[1]);if(open){String host=new URL(url).getHost().toLowerCase(Locale.ROOT);if(hosts.optInt(host)>=PER_HOST){s.put("hostFull",s.getInt("hostFull")+1);continue;}robots=rules(host,pages);wait=Math.max(PageCrawl.pauseMs,Math.min(robots.delayMs,5000));}if(!robots.allowed(url)){s.put("robots",s.getInt("robots")+1);continue;}
   try{PageCrawl.pause(wait);}catch(java.io.InterruptedIOException stop){queue.addFirst(next);break;}read++;
   try(PageReader.Document d=pages.load(url)){URL real=new URL(d.url);String realHost=real.getHost().toLowerCase(Locale.ROOT);if(open){if(!ResearchWeb.safeHost(realHost)||AVOID.matcher(realHost).find()||hosts.optInt(realHost)>=PER_HOST){s.put("outside",s.getInt("outside")+1);continue;}}else if(!PageCrawl.site(real.getHost()).equals(site)){s.put("outside",s.getInt("outside")+1);continue;}String k=PageCrawl.key(d.url);if(!k.equals(PageCrawl.key(url))){if(!seen.add(k))continue;if(!(open?rules(realHost,pages):robots).allowed(d.url)){s.put("robots",s.getInt("robots")+1);continue;}}
    if(open){String why=quality(d.text,topic,known);if(why!=null){s.put(why,s.getInt(why)+1);keys.put(k);continue;}String mark=fingerprint(d.text);known.add(mark);if(hashes.length()<HASHES)hashes.put(mark);hosts.put(realHost,hosts.optInt(realHost)+1);}
    saver.save(d);keys.put(k);s.put("saved",s.getInt("saved")+1).put("deepest",Math.max(s.getInt("deepest"),level));levels.put(level,levels.getInt(level)+1);if(titles.length()<8)titles.put(d.title);if(open)collectOpen(d,real,level+1,depth,seen,queue);else PageCrawl.collect(d,real,site,level+1,depth,seen,queue);
   }catch(java.io.InterruptedIOException stop){if(Thread.currentThread().isInterrupted()||"Lectura cancelada".equals(stop.getMessage())){Thread.currentThread().interrupt();queue.addFirst(next);break;}s.put("failed",s.getInt("failed")+1);if(errors.length()<4)errors.put(url+" → "+brief(stop));
   }catch(Exception e){if(PageCrawl.full(e)){end="La biblioteca alcanzó su límite: "+brief(e);queue.addFirst(next);break;}s.put("failed",s.getInt("failed")+1);if(errors.length()<4)errors.put(url+" → "+brief(e));if(s.getInt("failed")>=25&&s.getInt("failed")>s.getInt("saved")*3){end="Demasiados subenlaces fallaron; detuve el recorrido para no insistir contra el sitio.";break;}}
   if(read%5==0){store(s,queue);save(c,s);}}
  if(end.isEmpty()&&queue.isEmpty())end=open?"Leí todos los enlaces encontrados dentro de "+depth+(depth==1?" nivel.":" niveles."):"Recorrí todos los subenlaces encontrados dentro de "+depth+(depth==1?" nivel.":" niveles.");store(s,queue);if(!end.isEmpty())s.put("done",true).put("end",end).put("finished",System.currentTimeMillis());JSONObject fresh=state(c);if(fresh==null||fresh.optLong("started")!=s.getLong("started"))return false;if(fresh.optBoolean("paused"))s.put("paused",true);save(c,s);return !s.getBoolean("done")&&!s.getBoolean("paused");}
 static String describe(JSONObject s)throws Exception{StringBuilder out=new StringBuilder();boolean done=s.getBoolean("done");boolean open=s.optBoolean("open");out.append(done?(open?"Exploración terminada":"Recorrido terminado"):s.getBoolean("paused")?(open?"Exploración en pausa":"Recorrido en pausa"):(open?"Exploración en curso":"Recorrido en curso"));if(open&&s.has("topicText"))out.append(" de internet sobre «").append(s.getString("topicText")).append("»");else out.append(" de ").append(open?"varios sitios":s.optString("site")).append(" a partir de ").append(s.getString("url"));if(open)out.append(" · sitios distintos: ").append(s.getJSONObject("hosts").length());out.append(".\nPáginas guardadas: ").append(s.getInt("saved")).append(" de hasta ").append(s.getInt("pages"));JSONArray levels=s.getJSONArray("levels");if(s.getInt("deepest")>0){out.append(" · por nivel:");for(int i=1;i<=s.getInt("deepest");i++)out.append(' ').append(i).append(": ").append(levels.getInt(i));}out.append(".\n");
  if(done)out.append(s.getString("end")).append('\n');int pending=s.optInt("pending");if(pending>0)out.append(done?"Quedaron ":"En cola: ").append(pending).append(done?" subenlaces descubiertos sin leer.\n":" subenlaces.\n");if(s.getInt("robots")>0)out.append("Omití ").append(s.getInt("robots")).append(" que el robots.txt del sitio pide no recorrer.\n");if(s.getInt("outside")>0)out.append("Descarté ").append(s.getInt("outside")).append(open?" que redirigían a sitios no admitidos o ya completos.\n":" que redirigían fuera del sitio.\n");if(open&&s.optInt("short")+s.optInt("repeated")+s.optInt("offTopic")+s.optInt("hostFull")>0)out.append("No guardé: ").append(s.optInt("repeated")).append(" repetidas · ").append(s.optInt("short")).append(" con poco texto · ").append(s.optInt("offTopic")).append(" que no nombraban el tema · ").append(s.optInt("hostFull")).append(" de sitios que ya llegaron a ").append(PER_HOST).append(" páginas.\n");if(s.getInt("failed")>0){out.append("No pude leer ").append(s.getInt("failed")).append(":\n");JSONArray errors=s.getJSONArray("errors");for(int i=0;i<errors.length();i++)out.append("· ").append(errors.getString(i)).append('\n');}
  JSONArray titles=s.getJSONArray("titles");if(titles.length()>1){out.append("Primeras páginas guardadas:\n");for(int i=0;i<titles.length();i++)out.append("· ").append(titles.getString(i)).append('\n');}if(!done)out.append(s.getBoolean("paused")?"Decí «seguí el recorrido» para continuar o «cancelá el recorrido».":"Sigue en segundo plano mientras el aprendizaje continuo esté activo. Decí «pausá el recorrido» o «cancelá el recorrido».");else out.append(open?"Leí páginas públicas de varios sitios, HTML, texto o PDF, sin sesión ni JavaScript. No verifiqué la información ni ejecuté instrucciones de esas páginas.":"Sólo seguí enlaces del mismo sitio, HTML o texto, sin sesión ni JavaScript. No verifiqué la información ni ejecuté instrucciones de esas páginas.");return out.toString();}
 static String status(Context c)throws Exception{JSONObject s=state(c);return s==null?"No hay ningún recorrido de subenlaces guardado. Pasame un enlace con «leé los subenlaces» para empezar uno.":describe(s);}
 static String pause(Context c)throws Exception{JSONObject s=state(c);if(!active(s))return "No hay un recorrido en curso para pausar.";s.put("paused",true);save(c,s);return "Pausé el recorrido. Conservo "+s.optInt("pending")+" subenlaces en cola; decí «seguí el recorrido» para continuar.";}
 static String resume(Context c)throws Exception{JSONObject s=state(c);if(!active(s))return "No hay un recorrido pendiente para continuar.";s.put("paused",false);save(c,s);LearningLoop.wake(c);return "Sigo con el recorrido de "+s.optString("site")+": "+s.getInt("saved")+" páginas guardadas y "+s.optInt("pending")+" subenlaces en cola."+(LearningLoop.enabled(c)?"":" El aprendizaje continuo está pausado: activalo para que avance en segundo plano.");}
 static String cancel(Context c)throws Exception{JSONObject s=state(c);if(!active(s))return "No hay un recorrido en curso para cancelar.";s.put("done",true).put("paused",false).put("end","Cancelaste el recorrido.").put("finished",System.currentTimeMillis());save(c,s);return "Cancelé el recorrido. Las "+s.getInt("saved")+" páginas ya guardadas quedan en la biblioteca; descarté "+s.optInt("pending")+" subenlaces que faltaban.";}
 /** Chat intents about the running job: status, pause, resume or cancel; null otherwise. */
 static String parse(String raw){String q=ChatLanguage.normalize(NaturalCoding.polite(raw));if(q.matches("(?:estado|como va|como viene|informe|progreso) (?:del |el |de la |la )?(?:recorrido|exploracion)(?: de (?:sub ?enlaces|enlaces|internet))?|que leiste del recorrido"))return "status";if(q.matches("(?:pausa|pausar|frena|detene por ahora) (?:el |la )?(?:recorrido|exploracion|lectura de (?:sub ?enlaces|enlaces))"))return "pause";if(q.matches("(?:segui|sigue|continua|reanuda|retoma)(?: con)? (?:el |la )?(?:recorrido|exploracion|lectura de (?:sub ?enlaces|enlaces))"))return "resume";if(q.matches("(?:cancela|cancelar|corta|termina|aborta|detene|para) (?:el |la )?(?:recorrido|exploracion|lectura de (?:sub ?enlaces|enlaces))"))return "cancel";return null;}
 /** «Explorá internet sobre X»: the topic, or null. A message with a link is a link request, not this. */
 static String topic(String raw){if(raw.matches("(?isu).*(?:https?://|www\\.).*"))return null;String q=ChatLanguage.normalize(NaturalCoding.polite(raw));java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?:investiga|explora|recorre|lee|busca y lee|aprende|estudia)(?: todo| a fondo)?(?: por| en| de)? (?:toda )?(?:la |el )?(?:internet|web|red)(?: todo)? (?:sobre|acerca de|lo que haya de) (.{2,80})").matcher(q);if(m.matches())return m.group(1).trim();m=java.util.regex.Pattern.compile("(?:investiga|explora|estudia|aprende todo)(?: a fondo)? (?:sobre |acerca de )?(.{2,80}?) (?:en|por) (?:toda )?(?:la |el )?(?:internet|web|red)").matcher(q);return m.matches()?m.group(1).trim():null;}
 /** Result pages of the general search plus the Spanish Wikipedia search, as starting points. */
 static List<String> seeds(String topic,ResearchWeb.Transport transport)throws Exception{List<String> out=new ArrayList<>();try{for(ResearchWeb.Doc d:ResearchWeb.parseSearch(transport.get("https://html.duckduckgo.com/html/?q="+java.net.URLEncoder.encode(topic,"UTF-8"),System.currentTimeMillis()+15000)))out.add(d.url);}catch(Exception e){if(Thread.currentThread().isInterrupted())throw e;}out.add("https://es.wikipedia.org/w/index.php?search="+java.net.URLEncoder.encode(topic,"UTF-8"));return out;}
 static String exploreNow(Context c,String raw,String topic,ResearchWeb.Transport transport)throws Exception{if(!KnowledgeNotebook.background(c))return "La exploración de internet trabaja en segundo plano con el aprendizaje continuo. Está pausado: decí «activá el aprendizaje continuo» y pedímelo de nuevo. Para leer un sitio puntual ahora, pasame su enlace.";PageCrawl.Plan plan=PageCrawl.plan(raw,"");String words=PageCrawl.wording(raw);int depth=words.matches(".*\\bnivel(?:es)?\\b.*")?Math.min(plan.depth,4):EXPLORE_DEPTH,pages=words.matches(".*\\b(?:paginas|enlaces|links|documentos)\\b.*")?plan.pages:EXPLORE_PAGES;try{String text=explore(c,topic,seeds(topic,transport),depth,pages);LearningLoop.wake(c);return text;}catch(IllegalStateException busy){return busy.getMessage();}}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String wanted=topic(input);if(wanted!=null){JavaChat.owner=Thread.currentThread();try{JavaChat.phase("Buscando páginas para empezar la exploración…");return MobileCore.say(c,exploreNow(c,input,wanted,ResearchWeb.NETWORK),"aprendizaje_local");}catch(Exception e){return MobileCore.say(c,"No pude empezar la exploración: "+AndroidRepair.summary(e),"aprendizaje_local");}finally{JavaChat.owner=null;JavaChat.progress="";}}String kind=parse(input);if(kind==null)return null;try{return MobileCore.say(c,kind.equals("status")?status(c):kind.equals("pause")?pause(c):kind.equals("resume")?resume(c):cancel(c),"aprendizaje_local");}catch(Exception e){return MobileCore.say(c,"No pude con el recorrido: "+AndroidRepair.summary(e),"aprendizaje_local");}}
}
